-- =============================================
-- 6. 经验颗粒（30条，覆盖典型 B2B 销售场景）
-- =============================================
INSERT INTO experience_grain (id, space_id, scene_tag, scene_description, expert_thought, standard_script, common_mistakes, applicable_condition, weight, quality_score, difficulty_level, status, helpful_count, unhelpful_count, created_at) VALUES
('60000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', '初次拜访', '客户说已有供应商时如何破局', '客户说已有供应商是防御性反应。破局关键：承认现状+找缝隙+留钩子。目标是成为备选。', '理解，大部分客户一开始都这么说。不过即使不换供应商，多一个参照对您判断性价比也是有帮助的。要不花10分钟，我给您看一个同行客户怎么在现有基础上每年省了30%运维成本的？', '急于否定现有供应商、一上来就报低价、滔滔不绝介绍功能而不是了解现状', '客户有现有供应商且合作超过1年', 1.5, 4.5, 'advanced', 'active', 23, 2, '2026-06-15 10:00:00'),

('60000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000001', '初次拜访', '第一通电话如何让客户愿意聊下去', '第一通电话的目标不是卖东西，是拿到下一次沟通的机会。30秒内说清：你是谁+找他原因+对他的价值。', '王总您好，我是星际软件的张伟。冒昧打搅您一分钟。我们最近帮XX公司的销售团队做了一套提效系统，3个月人效提升了25%。刚好看到您这边也在扩张销售团队，方便聊两句吗？', '开场超过30秒还在自我介绍、用"能耽误您几分钟吗"这类自我矮化用词、客户说忙就直接挂断', 'B2B电话拓客，客户为部门总监及以上级别', 1.3, 4.0, 'intermediate', 'active', 18, 3, '2026-06-15 10:10:00'),

('60000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000001', '需求挖掘', '客户说不清楚需求时如何挖掘', '客户说"不知道""都行"往往不是真的没需求，而是需求没被激活或不知道怎么表达。用"现状-痛点-影响"三连问。', '张总，我做销售这么多年，发现一个规律：客户最痛苦的点，往往不是他们主动说的那个。我换个方式问——如果现在有一样东西必须改变，您最想让什么变得不一样？', '客户说不清楚就自顾自介绍产品、问一堆预设问题没认真听回答、错过客户的"其实..."转折', 'SaaS软件售前需求访谈，客户表达模糊', 1.2, 4.2, 'intermediate', 'active', 15, 4, '2026-06-15 10:20:00'),

('60000000-0000-0000-0000-000000000004', '30000000-0000-0000-0000-000000000001', '竞品对比', '客户说竞品便宜30%', '价格异议的本质是价值认知不对等。别急着降价，先问清比较口径：功能对齐、隐性成本、后续投入、风险成本，四个维度拉开差距。', '这个我理解，如果只看单价数字确实有差距。不过咱们一起打开看一下——XX的报价里包含运维服务了吗？二次开发费用怎么算？他们有多少个跟您同行业的成功案例？通常这三项摊进去，总成本反而更高。', '立刻降价或申请折扣、贬低竞品、回避价格问题转而聊功能', 'B2B软件销售竞品对比阶段，竞品报价明显更低', 1.5, 4.8, 'advanced', 'active', 31, 1, '2026-06-15 10:30:00'),

('60000000-0000-0000-0000-000000000005', '30000000-0000-0000-0000-000000000001', '价格谈判', '客户要求打折而利润空间有限', '让步要有交换——每一分折扣都要换一个条件（更长合同期、更快付款、更多部门覆盖）。让客户觉得是自己"赚到"的。', '这样张总，我这边能帮您争取到的空间确实有限。但如果您能签三年而不是一年，我可以跟公司申请把三年总价压到XX，算下来每年相当于85折。您看这个方案对您来说合适吗？', '没谈条件就降价、连续降价（每次都说是最低了又往下降）、最后一轮还主动降价', 'B2B合同谈判后期，客户已确认意向但要求价格让步', 1.4, 4.6, 'advanced', 'active', 27, 2, '2026-06-16 09:00:00'),

('60000000-0000-0000-0000-000000000006', '30000000-0000-0000-0000-000000000001', '合同推进', '签合同前客户突然失联一周', '断联是危险信号——内部在评估竞品、预算被砍或决策人变了。主动出击但别显得焦虑。给对方一个"台阶"回复：发行业报告而非"您考虑得怎样了"。', '王总，刚看到一份最新行业报告，提到你们行业明年数字化预算要翻倍。感觉跟咱们上次聊的方案正好契合，发给您参考一下。另外下周我去你们园区拜访另一家客户，方便的话顺便当面同步下项目进度？', '连发多条"在吗""考虑得怎样"、找对方同事/下属打听、坐等什么都不做', '合同推进阶段，客户突然中断沟通超过5天', 1.3, 4.3, 'intermediate', 'active', 19, 5, '2026-06-16 09:30:00'),

('60000000-0000-0000-0000-000000000007', '30000000-0000-0000-0000-000000000001', '需求挖掘', '客户需求与产品不匹配时', '硬推不匹配的产品是短视。坦诚告知边界反而建立信任。能在匹配部分做到极致，完全不匹配就推荐更合适的方案（哪怕是竞品）。', '王总坦白说，您提的这个场景我们目前确实覆盖得不够好，我不能为了签单忽悠您。不过您提到的另外两个需求——销售过程管理和团队协作——恰好是我们的强项。要不我们先聚焦这两块？', '掩饰产品短板夸大能力、直接放弃不再跟进、勉强承诺定制开发', 'SaaS产品销售，客户部分需求超出产品覆盖范围', 1.1, 4.1, 'intermediate', 'active', 12, 1, '2026-06-16 10:00:00'),

('60000000-0000-0000-0000-000000000008', '30000000-0000-0000-0000-000000000001', '高层汇报', '向CXO做30分钟方案汇报', 'CXO关心三件事：ROI、风险、时间线。用"3分钟结论+27分钟支撑"。开场第一句话量化价值。', '各位领导好，今天我用30分钟汇报三个问题：第一投多少钱——整体方案和费用结构；第二赚多少——12个月ROI测算；第三怎么落地——分三阶段实施，每阶段有明确验收标准。中间任何疑问随时打断我。', '花20分钟讲公司和产品背景、用满屏小字技术架构图、没有量化ROI数据', 'B2B销售后期，面向VP/CXO级别的方案汇报', 1.6, 4.7, 'master', 'active', 34, 3, '2026-06-16 10:30:00'),

('60000000-0000-0000-0000-000000000009', '30000000-0000-0000-0000-000000000001', '异议处理', '客户说公司太小/太新了不稳定', '公司实力的质疑是信任问题。别辩解，用"承认+证据+承诺"公式。', '您提的这个问题特别关键，换我是您也会担心。我给您看三个数据：一是120家付费客户续约率92%；二是XX银行和XX集团都是我们的客户，我们有专门客户成功团队7x24响应；三是合同里会写明SLA条款，达不到服务标准可按比例退款。', '讲创始人和融资故事试图证明"我们不差"、拿不出具体数据、过度承诺兜底条款', '创业公司SaaS产品销售，客户质疑公司规模和稳定性', 1.4, 4.4, 'advanced', 'active', 21, 4, '2026-06-17 11:00:00'),

('60000000-0000-0000-0000-00000000000a', '30000000-0000-0000-0000-000000000001', '需求挖掘', '客户预算有限但需求很大', '预算不足不是死局。先做"最小可行方案"，在有限预算内跑出效果数据，用效果撬动更多预算。帮客户算账：不做的损失>少做的成本>全做的成本。', '李总我完全理解预算压力。要不咱们换个思路——不追求一步到位，先聚焦最痛的那个环节。比如销售过程不透明这个问题，先用基础版跑三个月，成本只要原方案40%。等数据出来您拿效果去申请明年预算，比现在硬推全量成功率高得多。', '强行推全量方案逼客户加预算、为成交把价格压到不可持续、放弃跟进觉得客户没诚意', 'B2B销售中后期，客户认可价值但预算有限', 1.2, 4.0, 'intermediate', 'active', 14, 6, '2026-06-17 11:30:00'),

('60000000-0000-0000-0000-00000000000b', '30000000-0000-0000-0000-000000000001', '竞品对比', '客户选型评估表里我们排名不靠前', '评估表排名不靠前是因为评估维度是竞品定义的。重新定义评估标准，把隐性需求（服务响应、定制灵活度、数据安全）拉成权重项。', '李总我看了你们的选型评分表，坦白说只看表上这几个指标我们确实不占优。但我在你们行业做了8年，发现真正影响满意度的往往是表外的三个东西：上线后的响应速度、需求变更的灵活度、数据出问题时的兜底能力。要不咱们针对这三个维度单独拉一张补充评估表？', '抱怨评估标准不公平、在现有指标上硬拼分数、放弃竞争', 'B2B招投标或选型阶段，多个供应商竞争', 1.3, 4.5, 'advanced', 'active', 25, 1, '2026-06-17 14:00:00'),

('60000000-0000-0000-0000-00000000000c', '30000000-0000-0000-0000-000000000001', '价格谈判', '客户用竞品报价压价', '永远不要匹配竞品的价格，要匹配竞品的价值。差异化捆绑：把竞品报不了的服务打包进去。', '他们的价格确实挺激进的。不过据我所知那个价格不含实施服务，光实施费一般要加30%。我们虽然报价高一些，但是含了3个月实施陪跑，相当于有个专职顾问帮你把团队带起来。算下来时间成本省了一大截。', '贬低竞品报价真实性、不做对比分析直接降价、绕开价格谈情怀', '竞品给出更低报价，客户以此为谈判筹码', 1.4, 4.2, 'intermediate', 'active', 16, 2, '2026-06-18 09:00:00'),

('60000000-0000-0000-0000-00000000000d', '30000000-0000-0000-0000-000000000001', '合同推进', '多部门联合决策时如何推进', '联决场景最大风险是"没人说不也没人说好"。画决策地图找真正决策者，逐个击破，制造FOMO。', '梳理了一下，目前涉及销售、IT、财务、采购四个部门。销售关心功能，IT关心安全和集成，财务关心ROI，采购关心合规。下周围绕这四个维度每个部门安排一次针对性15分钟交流。特别是IT这边，安排我们技术负责人亲自来讲安全架构。', '只跟一个人沟通等他自己推动、给所有人发同一份PPT、催促但没降低决策成本', 'B2B大客户销售，涉及多部门联合决策', 1.5, 4.6, 'advanced', 'active', 28, 3, '2026-06-18 10:00:00'),

('60000000-0000-0000-0000-00000000000e', '30000000-0000-0000-0000-000000000001', '异议处理', '客户说先内部讨论一下就没了下文', '"内部讨论一下"是决策拖延的委婉说法。必须锁定两个东西：讨论的具体议题是什么、下次沟通的具体时间。', '好的没问题。为帮您提高讨论效率，我帮您整理一份一页纸的决策备忘——把方案的三个核心优势、两个风险点和预算区间都列清楚，您直接拿这个去会上讨论。另外咱们先定一下下次交流的时间，下周三还是周四方便？', '说"好的您慢慢讨论"然后被动等待、追问"讨论得怎么样了"制造压力、绕过联系人直接找其他决策者', '初步沟通后客户表示需内部讨论但不给明确时间', 1.2, 3.8, 'intermediate', 'active', 11, 7, '2026-06-18 11:00:00'),

('60000000-0000-0000-0000-00000000000f', '30000000-0000-0000-0000-000000000001', '初次拜访', '展会上如何快速筛选有效线索', '展会一天收上百张名片，90%无效。30秒筛选法：名片经理及以上、对方主动提具体场景或痛点、现场做了Demo并留微信。满足两个就是有效线索。', '（现场交流）感谢您停下来了解。我想确认一下——您刚才提到的XX问题，是目前正在做方案选型还是只是了解一下？如果正在选型的话，我可以安排技术团队针对您的场景做一个定制Demo，大概15分钟。', '见人就发资料不加筛选、现场聊太深耽误接待其他客户、展会后群发千篇一律的跟进邮件', '行业展会、技术峰会等线下活动获客场景', 1.0, 3.5, 'beginner', 'active', 8, 2, '2026-06-19 09:00:00'),

('60000000-0000-0000-0000-000000000010', '30000000-0000-0000-0000-000000000001', '价格谈判', '快到季度末差业绩怎么谈', '季末冲单不能暴露你急。把"你需要成交"包装成"客户需要这个时机"。用"季度末财务结算窗口""下季度价格调整""优先排期名额"等客观理由。', '李总我说一个实际情况您参考——我们公司每个季度末财务有一次集中结算，这个时候签合同可以锁定当季价格政策。下季度因产品升级价格可能有调整。我建议咱们周五前把合同定下来，同时帮您争取VIP实施优先排期，下周就可进场。', '暴露业绩压力求客户帮忙、不断降价试图快速成交、对没意向的客户也强行冲单', '季度末业绩冲刺，有意向但犹豫的客户', 1.3, 4.1, 'intermediate', 'active', 14, 8, '2026-06-19 10:00:00'),

('60000000-0000-0000-0000-000000000011', '30000000-0000-0000-0000-000000000001', '高层汇报', 'CEO突然问凭什么相信你', '不是挑衅，是给你展示真本事。回答：一个数据+一个案例+一个承诺。数据证明结果，案例证明可复制，承诺兜底风险。', '张总这个问题问得好。我给您三个信息：第一过去三年我们服务了47家跟贵司同规模的企业，平均人效提升22%；第二XX集团去年上了我们系统，12个月ROI做到3.8倍；第三我们合同里有明确KPI考核条款，达不到约定效果按比例退款。这就是我的底气。', '开始自我推销讲公司历史、支支吾吾拿不出数据、过度承诺无法兑现的条件', 'B2B销售高层会面，CEO突然发难测试可信度', 1.5, 4.9, 'master', 'active', 37, 0, '2026-06-19 14:00:00'),

('60000000-0000-0000-0000-000000000012', '30000000-0000-0000-0000-000000000001', '合同推进', '合同金额大需要法务审批', '法务审批是合规流程不是障碍。提前准备法务关注的6个核心条款（数据安全、SLA、知识产权、解约条款、赔偿责任、争议解决）用通俗语言解释清楚。', '王律师我知道您关注几个核心点——数据安全等级、服务可用性承诺、知识产权归属。我给您准备了一份对照表：左边是我们条款，右边是行业标准条款（XX云和XX软件的同款），您看一下我们的条款在同类产品里是什么水平。如果还有顾虑我让我们法务直接跟您对。', '绕过法务催业务签字、遇法务异议就找对方业务施压、法务提修改意见全盘接受', 'B2B大单签约，金额超百万需经客户法务审批', 1.2, 4.3, 'advanced', 'active', 17, 2, '2026-06-20 09:00:00'),

('60000000-0000-0000-0000-000000000013', '30000000-0000-0000-0000-000000000001', '异议处理', '客户担心数据迁移风险', '数据迁移恐惧是B2B SaaS最大隐形杀手。化解：承认风险+详细迁移计划+兜底方案。', '数据迁移确实是项目里最让人紧张的环节，完全理解。我们做法是分三步：第一步先在测试环境跑一遍验证数据完整性；第二步选业务低峰期做正式迁移全程工程师驻场；第三步迁移后保留原系统数据30天作为回滚保险。我们做了上百次迁移没丢过一次数据。', '轻描淡写说"很快的没问题"、没有具体迁移时间表、不考虑回滚方案', '替换型SaaS销售，客户需从旧系统迁移数据', 1.4, 4.5, 'advanced', 'active', 20, 1, '2026-06-20 10:00:00'),

('60000000-0000-0000-0000-000000000014', '30000000-0000-0000-0000-000000000001', '客户维护', '客户上线后满意度下降', '上线后"失望期"是正常的。必须前30天主动管理预期：每周同步进度和问题清单、快速解决一个小痛点建立信任、把长期价值拆成小里程碑逐步兑现。', '王总上线两周了，我梳理了进度报告：目前已完成70%配置，销售团队已经可用。但数据导入比预期慢了两天，因旧系统导出格式较乱。已安排专人处理，预计下周三全部就绪。另外我发现一个可快速见效的点——日报自动生成功能已可用，要不要先让团队用起来？', '上线后撒手不管开始追新客户、对问题避重就轻、等客户投诉了才被动响应', '已签约客户上线后1-4周出现使用问题或满意度下降', 1.3, 4.0, 'intermediate', 'active', 9, 3, '2026-06-20 14:00:00'),

('60000000-0000-0000-0000-000000000015', '30000000-0000-0000-0000-000000000001', '需求挖掘', '需求文档需求太多如何聚焦', '需求越多越要收缩。二八法则找到20%需求创造80%价值。三问法：不做哪个损失最大？哪个做好能让老板看到效果？哪个跟你KPI直接挂钩？', '李总我看了需求文档，43个需求点确实很全面。不过根据经验一次性全做反而容易出问题。我建议用二八法则筛一下——列一下每个需求对核心指标（如销售人效或成交率）的影响，把前8个作为第一期先跑出效果。这是典型的小步快跑策略。', '试图满足所有需求导致项目失控、擅自删减需求不与客户确认、按自己理解排序而非客户优先级', '客户发了详细需求文档，需求点众多缺乏明确优先级', 1.1, 3.9, 'intermediate', 'active', 10, 2, '2026-06-21 09:00:00'),

('60000000-0000-0000-0000-000000000016', '30000000-0000-0000-0000-000000000001', '竞品对比', '免费开源竞品威胁', '开源不是免费——隐性成本包括部署、维护、安全、迭代。算总账比算单价。核心：如果你有5人IT团队且不差时间，开源是好的。如果你的核心业务是销售而非软件开发，SaaS更划算。', '开源确实是很好的技术路线，我们团队也有很多开源贡献者。不过从总成本来看，上开源需要至少两个后端工程师维护，加上服务器、安全加固、二次开发，一年人力成本至少60万起步。我们SaaS版年费不到20万包含了所有这些，性价比其实更高。而且出了问题有人兜底。', '贬低开源说"不靠谱"、不帮客户算总拥有成本、忽略开源在技术团队强的大客户的竞争力', '竞品是开源产品，客户技术团队有一定能力', 1.3, 4.4, 'advanced', 'active', 22, 4, '2026-06-21 10:00:00'),

('60000000-0000-0000-0000-000000000017', '30000000-0000-0000-0000-000000000001', '客户维护', '客户要求退款或解约', '退费危机的核心不是钱的问题，是信任崩塌。三步：第一时间高层介入、还原事实（产品问题还是使用问题）、给出改善方案+退出方案两个选项。', '张总非常抱歉让您有这种体验。我马上安排两件事：第一明天我带着客户成功总监当面跟您复盘把问题逐条过；第二不管最终怎么决定我今天先安排技术团队排查您提到的那三个Bug，确认是我们的问题本周内修复并补偿一个月服务费。您看这样行吗？', '推卸责任说"是客户不会用"、只退款不谈挽回、层层上报让客户等很久', '已签约客户因产品问题或服务不满提出退款/解约', 1.6, 4.8, 'master', 'active', 40, 0, '2026-06-21 14:00:00'),

('60000000-0000-0000-0000-000000000018', '30000000-0000-0000-0000-000000000001', '初次拜访', '过前台/门神关卡', '过前台不是骗，是让前台觉得放你进去对ta有好处。提前查清要找的人全名和职位，态度温和但笃定。', '（拿着笔记本微笑）你好，我跟销售部张总监约了10点聊系统合作的事，麻烦帮我通知一下，谢谢。', '撒谎说有预约、硬闯、对前台态度傲慢', '上门拜访或电话时被非决策人拦截', 1.0, 3.2, 'beginner', 'active', 6, 3, '2026-06-22 09:00:00'),

('60000000-0000-0000-0000-000000000019', '30000000-0000-0000-0000-000000000001', '异议处理', '客户说等明年预算下来再说', '"等明年预算"意味着你的价值主张不够紧迫。帮客户量化拖延成本：继续用现状每月损失多少。如果拖延6个月损失>年费，现在上就是省钱。', '张总等到明年的想法我理解，预算周期确实要考虑。不过咱们先算一笔账——您现在团队25个人，每个月因销售过程不透明造成的丢单和重复劳动保守估计至少损失8万。等到明年3月就是6个月48万。而我们的年费是30万，现在签约反而是省钱的。', '催促逼单让客户反感、默认接受"等明年"不再跟进、不给客户提供说服预算部门的数据弹药', '年度末或年初客户以预算周期为由推迟采购', 1.2, 4.1, 'intermediate', 'active', 13, 3, '2026-06-22 10:00:00');

-- 补充颗粒（续）
INSERT INTO experience_grain (id, space_id, scene_tag, scene_description, expert_thought, standard_script, common_mistakes, applicable_condition, weight, quality_score, difficulty_level, status, helpful_count, unhelpful_count, created_at) VALUES
('60000000-0000-0000-0000-00000000001a', '30000000-0000-0000-0000-000000000001', '客户维护', '老客户续约时要求更多功能折扣', '续约是存量战争比新签更值钱。谈判核心不是压价是展示过去一年价值创造。用数据说话：上线前后对比、ROI达成率、团队使用率。', '王总续约的事咱们回顾一下过去这年——您团队48个人，CRM活跃度从上线初30%到现在85%，商机跟进了1200个，成交周期缩短15天。算下来一年帮团队多创造了差不多300万增量。续约的话我帮您锁住现在价格，新产品模块也按老客户优惠给您。', '只看续约折扣不谈创造价值、客户不提续约就默认自动续、续约季才联系客户平时没维护', '已签约满一年的老客户面临续约谈判', 1.4, 4.7, 'advanced', 'active', 29, 1, '2026-06-23 09:00:00'),

('60000000-0000-0000-0000-00000000001b', '30000000-0000-0000-0000-000000000001', '需求挖掘', '客户IT部门技术评估后给了负面意见', 'IT部门负面意见往往是"能不做就不做"的保守心态。策略不是硬刚而是把IT变成项目同盟：承认合理关切+安全认证和架构图打消顾虑+把项目跟IT自身KPI绑定。', '陈工您提的这三个技术问题非常专业——API并发量、数据隔离级别、灾备方案。我让我们架构师针对这三点出了一份技术白皮书您看一下。另外注意到你们团队今年也有上云和微服务改造目标，其实我们系统在部署层面可以帮你们沉淀一套云原生的最佳实践，对你们后续架构演进也有参考价值。', '觉得IT故意刁难开始对立、跳过IT直接找业务领导施压、技术问题回答不上来敷衍', 'B2B销售中后期IT部门在技术评估环节给负面意见', 1.4, 4.6, 'advanced', 'active', 24, 2, '2026-06-23 10:00:00'),

('60000000-0000-0000-0000-00000000001c', '30000000-0000-0000-0000-000000000001', '合同推进', '口头承诺了但合同迟迟不签', '不签合同原因只有一个——还不够痛。重新激活痛点：给客户分享同行数据，"XX公司推迟3个月上线中间丢了两个大单损失80万"。用真实案例脱敏处理。', '张总合同的事咱们确认一下还有哪些地方需要调整。另外分享一个情况供参考——上个月我们一个客户也是在这个阶段犹豫了两个月，后来竞品抢在前面上了一套类似系统结果丢了一个大客户。时机这个东西确实有时候比价格更重要。', '反复催"合同签了吗"没有新信息、给客户施压"不签就涨价"、自己降价推动签约', '客户口头确认意向但迟迟不签合同超过两周', 1.3, 4.2, 'intermediate', 'active', 15, 6, '2026-06-23 14:00:00'),

('60000000-0000-0000-0000-00000000001d', '30000000-0000-0000-0000-000000000001', '异议处理', '客户被竞品挖走又回来找你', '吃回头草的客户是最高质量线索。不要"我早说过"，帮ta体面地回来。欢迎+不提之前决策+快速推进。', '王总欢迎！之前方案我快速更新一下——这半年我们产品迭代了三个大版本，您上次关心的几个功能都已上线。要不我明天下午带最新版过来给您做个演示，争取一周内把合同敲定？', '幸灾乐祸说"我早说过"、借机大幅抬价、拖慢节奏不抓住机会窗口', '客户之前选择竞品但现在不满意重新联系', 1.5, 4.6, 'advanced', 'active', 33, 0, '2026-06-24 09:00:00'),

('60000000-0000-0000-0000-00000000001e', '30000000-0000-0000-0000-000000000001', '价格谈判', '客户说方案很好就是太贵了', '最好的信号——客户已认可价值只是价格心理门槛。拆解"贵"的真实含义：超出预算上限、比竞品贵、还是觉得不值这个价？三种情况三种解法。', '谢谢认可方案！您说的"贵"我想确认一下具体是指——超出了今年预算盘还是对比下来比别人贵还是觉得投入产出不值这个价？不同情况我的解法不一样，您方便的话咱们敞开聊聊。', '直接问"那您预算多少"、上来就谈折扣、把"贵"当拒绝信号放弃', '客户明确表示认可方案价值但对价格有异议', 1.3, 4.3, 'intermediate', 'active', 18, 2, '2026-06-24 10:00:00'),

('60000000-0000-0000-0000-00000000001f', '30000000-0000-0000-0000-000000000001', '异议处理', '客户问你们和XX公司比有什么优势', '优势不是自己说的，是让客户自己推导出来的。反问式对比：不问"我们哪里好"，问"您觉得XX公司的产品用下来最不满意的是什么"——痛点就是我们的切入点。', '张总与其我来说我们的优势，不如换个角度——您觉得XX公司用下来最不满意的是什么？是响应速度、功能更新还是数据报告？您告诉我痛点，我告诉您我们怎么解决的。这样比我自己王婆卖瓜更有说服力。', '罗列一堆功能对比表格让人眼花、贬低竞品、说不出差异化只会说我们服务好', '客户同时在评估多个供应商主动问差异化', 1.0, 3.8, 'intermediate', 'active', 7, 1, '2026-06-25 09:00:00');

-- =============================================
-- 7. 对话会话
-- =============================================
INSERT INTO skill_conversation (id, skill_id, user_id, title, mode, created_at) VALUES
('70000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000004', '客户说价格太贵怎么回应', 'qa', '2026-07-01 09:15:00'),
